import{DEMO_ID,demoCourse,distance,validPoint,uid,osmCourse,validateBackup,gpsFromJpeg}from'./core.js';
import {oakTrail} from './oak-trail.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={play:'M4 20V3m0 1 13 4-13 4M2 21h7',courses:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',scorecard:'M6 3h12v18H6zM9 7h6M9 11h1m4 0h1m-6 4h1m4 0h1',bag:'m7 7 2 14h9l2-14H7Zm3 0L8 2m5 5 1-5m2 5 4-4M6 7h15M5 10l-2 2v6h5',rounds:'M4 5v5h5M4 10a8 8 0 1 1 0 5m8-10v7l4 2',gps:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v4m0 12v4M2 12h4m12 0h4',arrow:'M5 12h14m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',flag:'M5 21V3l14 4-14 5',camera:'M3 7h4l2-3h6l2 3h4v13H3V7Zm9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',check:'m4 12 5 5L20 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.flag}"/></svg>`;
const defaults={courses:[demoCourse()],rounds:[],selected:DEMO_ID,hole:0,units:'yd',bag:[{name:'Driver',distance:230},{name:'3 wood',distance:210},{name:'5 wood',distance:195},{name:'4 iron',distance:180},{name:'5 iron',distance:170},{name:'6 iron',distance:160},{name:'7 iron',distance:150},{name:'8 iron',distance:140},{name:'9 iron',distance:125},{name:'Pitching wedge',distance:110},{name:'Gap wedge',distance:95},{name:'Sand wedge',distance:80}]};
defaults.courses.unshift(structuredClone(oakTrail));defaults.selected=oakTrail.id;
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('fairway-v1')||'null')};}catch{state=structuredClone(defaults);}
if(!state.courses.some(c=>c.id===oakTrail.id)){state.courses.unshift(structuredClone(oakTrail));if(state.selected===DEMO_ID&&!state.rounds.length){state.selected=oakTrail.id;state.hole=0;}}
let view='play',map,features,positionLayer,targetLayer,baseLayer,overlayLayers,photos=[],gps=null,watch=null,editor=false,editPoint='tee',target=null,shotStart=null,searchResults=[],layer='course',wakeLock=null,photoDraft=null,toastTimer,gpsRefresh;
function save(){try{localStorage.setItem('fairway-v1',JSON.stringify(state));return true;}catch{toast('Device storage is full. Export a backup before continuing.');return false;}}
const course=()=>state.courses.find(c=>c.id===state.selected)||state.courses[0];
const hole=()=>course().holes[Math.min(state.hole,course().holes.length-1)];
const active=()=>state.rounds.find(r=>r.courseId===course().id&&!r.finished);
const fresh=()=>gps&&Date.now()-gps.time<30000;
const origin=()=>course().source==='demo'?[hole().center[0]-.00132,hole().center[1]-.00036]:fresh()?gps.point:null;
const units=()=>state.units==='m'?'m':'yd';
const measure=m=>m==null?'—':Math.round(m*(state.units==='m'?1:1.0936133)).toLocaleString();
const scoreTotal=r=>r.holes.reduce((s,h)=>s+(h.score??0),0);
const played=r=>r.holes.filter(h=>h.score!=null);
const relative=r=>played(r).reduce((s,h)=>s+h.score-h.par,0);
const parText=n=>n===0?'E':n>0?`+${n}`:String(n);
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function dialog(title,subtitle,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!$('#dialog').open)$('#dialog').showModal();}
function close(){if($('#dialog').open)$('#dialog').close();}
function heading(title,sub,action=''){return`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function button(action,label,style='',extra=''){return`<button class="button ${style}" data-action="${action}" ${extra}>${label}</button>`;}
const navItems=[['play','Play golf'],['courses','My courses'],['scorecard','Scorecard'],['bag','My bag'],['rounds','Round history']];
function navigate(){let next=location.hash.slice(1)||'play';if(!navItems.some(n=>n[0]===next))next='play';if(next!==view){editor=false;target=null;}view=next;render();}
function render(){if(map){map.remove();map=null;}$('#navigation').innerHTML=navItems.map(([key,label])=>`<a class="nav-link ${view===key?'active':''}" href="#${key}">${icon(key)}<span>${label}</span></a>`).join('');$('#mobile-nav').innerHTML=navItems.map(([key,label])=>`<a class="mobile-link ${view===key?'active':''}" href="#${key}" ${view===key?'aria-current="page"':''}>${icon(key)}${key==='rounds'?'History':key==='scorecard'?'Score':label}</a>`).join('');$('#breadcrumb').innerHTML=`Your clubhouse <span>/</span> ${navItems.find(n=>n[0]===view)[1]}`;$('#content').innerHTML=({play:playView,courses:coursesView,scorecard:scoreView,bag:bagView,rounds:roundsView}[view])();if(view==='play'){initMap();updateYardages();}connection();}
function playView(){const c=course(),h=hole(),r=active(),s=r?.holes[state.hole];return heading('Your game. Your way.','A little more confidence with every shot.',button('find',`${icon('plus')} Find a course`,'secondary'))+`<div class="play-layout"><div class="left-column"><section class="card course-card"><span class="label">ON THE COURSE</span><div class="course-title"><h2>${esc(c.name)}</h2><span class="tag">${c.source==='demo'?'DEMO':c.source==='OpenStreetMap'?'OSM':'MY COURSE'}</span></div><p>${c.source==='demo'?'Fictional practice course · sample distances':`${c.holes.length} holes · ${esc(c.source)} · check mapped points`}</p><div class="hole-strip"><div class="hole-title"><strong>${String(h.number).padStart(2,'0')}</strong><small>HOLE</small></div><div class="hole-info"><span>PAR <b>${h.par}${h.parEstimated?'*':''}</b></span><span><b>${measure(distance(h.tee,h.center))}</b> ${units()}</span></div><div class="arrow-group"><button class="arrow-btn" data-action="prev" aria-label="Previous hole" ${state.hole===0?'disabled':''}>‹</button><button class="arrow-btn" data-action="next" aria-label="Next hole" ${state.hole>=c.holes.length-1?'disabled':''}>›</button></div></div></section><section class="distance-card"><div class="distance-heading">DISTANCE TO GREEN <span class="live-pill" id="gps-pill">${c.source==='demo'?'DEMO POSITION':'GPS OFF'}</span></div><div class="center-distance"><span class="number" id="yard-center">—</span><small>${units().toUpperCase()}</small><p>TO THE CENTER</p></div><div class="edge-distances"><div><strong id="yard-front">—</strong><span>FRONT</span></div><div><strong id="yard-back">—</strong><span>BACK</span></div></div><div class="distance-footer" id="gps-status">${c.source==='demo'?'Sample yardages · not a real course':'Enable GPS to see live distances'}</div></section><section class="card quick-score"><div class="section-row"><h3>Your score · hole ${h.number}</h3><a class="link" href="#scorecard">Full scorecard ↗</a></div><div class="counter-row"><span class="counter-label">Strokes</span><div class="counter"><button data-action="stroke-minus" aria-label="Remove a stroke">−</button><strong id="quick-strokes">${s?.score??'—'}</strong><button data-action="stroke-plus" aria-label="Add a stroke">+</button></div></div><div class="counter-row"><span class="counter-label">Putts</span><div class="counter"><button data-action="putt-minus" aria-label="Remove a putt">−</button><strong id="quick-putts">${s?.putts??'—'}</strong><button data-action="putt-plus" aria-label="Add a putt">+</button></div></div><div class="score-bottom"><span>ROUND TOTAL &nbsp; <b id="quick-total">${r?scoreTotal(r):'—'}</b></span><span id="quick-relative">${r&&played(r).length?`${parText(relative(r))} through ${played(r).length}`:'Ready when you are'}</span></div></section>${target?targetCard():''}</div><section class="card map-card"><div class="map-toolbar"><h3>${icon('courses')} Hole overview</h3><div class="segmented" aria-label="Map layer"><button data-action="layer" data-value="course" class="${layer==='course'?'active':''}">Course</button><button data-action="layer" data-value="aerial" class="${layer==='aerial'?'active':''}">US aerial</button></div></div>${editor?editorPanel():''}<div id="map" aria-label="Golf hole map"></div><div class="map-bottom"><div class="map-hint" id="map-hint">${editor?'Tap the map to place your selected point.':'Tap anywhere to plan your next shot.'}</div>${button('gps',`${icon('gps')} ${watch!=null?'GPS on':'Use my GPS'}`)}</div></section></div><div class="below-play"><div class="card mini-card"><div class="mini-icon">${icon('flag')}</div><div><span class="label">${r?'ROUND IN PROGRESS':'LET’S PLAY'}</span><strong>${r?`${played(r).length} / ${c.holes.length}`:'Start a round'} <small>${r?'holes recorded':''}</small></strong></div><button class="link" style="margin-left:auto" data-action="${r?'finish':'start'}" aria-label="${r?'Finish round':'Start round'}">${r?'Finish ↗':'↗'}</button></div><div class="card mini-card"><div class="mini-icon">${icon('bag')}</div><div><span class="label">SHOT TRACKER</span><strong id="shot-live">${shotStart?'Tracking…':'Every shot counts'}</strong></div><button class="link" style="margin-left:auto" data-action="shot" aria-label="Track a shot">${shotStart?'Stop':'↗'}</button></div><div class="card mini-card"><div class="mini-icon">${icon('courses')}</div><div><span class="label">MAKE IT YOURS</span><strong>Map this course</strong></div><button class="link" style="margin-left:auto" data-action="edit" aria-label="Map course">↗</button></div></div>`;}
function targetCard(){const o=origin()||hole().tee;return`<div class="card target-card"><div class="section-row"><span class="label">SHOT PLANNER</span><button class="link" data-action="clear-target">Clear ×</button></div><p><strong>${measure(distance(o,target))}</strong> <small>${units()} ${origin()?'from your position':'from tee · preview'}</small></p><small>${measure(distance(target,hole().center))} ${units()} remaining to green</small></div>`;}
function editorPanel(){return`<div class="editor-panel"><div class="section-row"><b style="font-size:11px">Course mapper · hole ${hole().number}</b><button class="link" data-action="editor-done">Done ✓</button></div><p>Choose a point, then tap its location. Changes save on this device.</p><div class="editor-steps">${['tee','front','center','back','hazard'].map(k=>`<button data-action="edit-point" data-value="${k}" class="${editPoint===k?'active':''} ${hole()[k]?'done':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><div class="editor-details"><span>Par</span><select id="edit-par" aria-label="Hole par">${[3,4,5,6].map(n=>`<option ${hole().par===n?'selected':''}>${n}</option>`).join('')}</select>${button('photo',icon('camera')+' Photo','secondary small')}${button('overlay','Aerial image','secondary small')}${button('clear-hole','Clear points','secondary small')}</div></div>`;}
function demoSvg(){let trees='';for(let i=0;i<160;i++){const x=(i*137.5)%720,y=(i*83.3)%1000;if(x>220&&x<530&&y>80&&y<900)continue;trees+=`<circle cx="${x}" cy="${y}" r="${9+i%11}" fill="${['#9cb379','#92ab6b','#b0c389','#86a263'][i%4]}"/><circle cx="${x-3}" cy="${y-3}" r="${5+i%6}" fill="#bbc992" opacity=".6"/>`;}
return`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 1000"><defs><pattern id="grass" width="18" height="18" patternUnits="userSpaceOnUse"><path d="m0 18 18-18" stroke="#f6f8db" stroke-width="6" opacity=".1"/></pattern><filter id="grain"><feTurbulence baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".075"/></feComponentTransfer></filter></defs><rect width="720" height="1000" fill="#d0ddb3"/><path d="M80 1040C60 780 200 620 175 430S160 130 280-40" fill="none" stroke="#bfcd9e" stroke-width="32"/><path d="M80 1040C60 780 200 620 175 430S160 130 280-40" fill="none" stroke="#e6e8ca" stroke-width="9"/>${trees}<path d="M327 917C285 860 281 748 310 654S350 510 336 424S319 291 347 212Q380 133 441 134Q519 151 500 231C480 300 461 327 463 394C465 510 424 577 401 666S391 846 369 914Z" fill="#b0c785"/><path d="M327 917C285 860 281 748 310 654S350 510 336 424S319 291 347 212Q380 133 441 134Q519 151 500 231C480 300 461 327 463 394C465 510 424 577 401 666S391 846 369 914Z" fill="url(#grass)"/><path d="M454 473C506 418 580 447 586 502C592 554 519 585 495 545C476 514 429 519 454 473Z" fill="#92bfc1"/><path d="M459 478C505 434 568 452 576 499" fill="none" stroke="#c6ddd2" stroke-width="4"/><path d="M301 375C279 362 285 315 305 303S339 303 331 329S324 389 301 375Z" fill="#e9dfb5" stroke="#c8be91" stroke-width="3"/><path d="M481 207C469 194 483 165 499 174S516 202 503 214Z" fill="#ede3bc" stroke="#c8be91" stroke-width="3"/><path d="M383 240C355 233 355 184 376 159S431 129 453 147S468 190 449 212S412 247 383 240Z" fill="#8da963" stroke="#a2ba75" stroke-width="6"/><path d="M382 223C366 211 371 181 389 165S426 143 443 156" fill="none" stroke="#acc180" stroke-width="2"/><rect x="317" y="887" width="51" height="26" rx="8" fill="#90aa64" transform="rotate(-8 340 900)"/><rect width="720" height="1000" filter="url(#grain)" opacity=".65"/></svg>`;}
function initMap(){const c=course(),h=hole();map=L.map('map',{zoomControl:false,attributionControl:true,maxZoom:21});L.control.zoom({position:'topright'}).addTo(map);features=L.layerGroup().addTo(map);positionLayer=L.layerGroup().addTo(map);targetLayer=L.layerGroup().addTo(map);overlayLayers=L.layerGroup().addTo(map);if(c.source==='demo'&&layer==='course'){const b=[[h.tee[0]-.0005,h.tee[1]-.0018],[h.tee[0]+.0038,h.tee[1]+.0025]];L.imageOverlay('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(demoSvg()),b).addTo(features);map.attributionControl.addAttribution('Illustrated demo · fictional course');}else addBase();drawHole();const pts=[h.tee,h.center,h.front,h.back].filter(Boolean);if(pts.length>1)map.fitBounds(pts,{padding:[75,65],maxZoom:18});else map.setView(c.center||h.tee||[40.75,-73.95],16);map.on('click',e=>mapClick([e.latlng.lat,e.latlng.lng]));loadPhotos();drawPosition();if(target)drawTarget();setTimeout(()=>map?.invalidateSize(),80);}
function addBase(){const aerial=layer==='aerial';baseLayer=L.tileLayer(aerial?'https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/{z}/{y}/{x}':'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxNativeZoom:aerial?16:19,maxZoom:21,attribution:aerial?'Imagery: <a href="https://www.usgs.gov/the-national-map-data-delivery/gis-data-download">USGS / USDA NAIP & partners</a>':'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>',keepBuffer:1}).addTo(map);let warned=false;baseLayer.on('tileerror',()=>{if(!warned){warned=true;toast(aerial?'Aerial imagery unavailable here. Try Course view or add your own image.':'Map tiles unavailable. Saved course points and GPS still work.');}});}
function marker(p,text,cls='',container=features){return L.marker(p,{icon:L.divIcon({className:'',html:`<div class="map-point ${cls}">${text}</div>`,iconSize:[30,30],iconAnchor:[15,15]})}).addTo(container);}
function drawHole(){const h=hole();for(const s of course().shapes||[]){const colors={fairway:'#b5cc8c',green:'#8db762',bunker:'#e8dbad',water_hazard:'#8dbfc9'};L.polygon(s.points,{color:colors[s.type],weight:1,fillColor:colors[s.type],fillOpacity:layer==='aerial'?.12:.55,interactive:false}).addTo(features);}if(h.green)L.polygon(h.green,{color:'#517a3b',weight:2,fillOpacity:.15,interactive:false}).addTo(features);if(h.tee&&h.center)L.polyline(h.path||[h.tee,h.center],{color:course().source==='demo'?'#fff':'#466b3c',weight:2,dashArray:'5 7',opacity:.8}).addTo(features);if(h.tee)marker(h.tee,'T').bindTooltip('Mapped tee · actual markers may differ');if(h.front)marker(h.front,'F').bindTooltip('Mapped front estimate');if(h.back)marker(h.back,'B').bindTooltip('Mapped back estimate');if(h.center)marker(h.center,'⚑','flag').bindTooltip('Green center · verify on course');for(const z of h.hazards||[]){marker(z.point,'!').bindTooltip(document.createTextNode(`${z.name} · ${measure(distance(origin()||h.tee,z.point))} ${units()} ${origin()?'from position':'from tee (preview)'}`));}if(h.referenceYards){const info=$('.hole-info span:last-child');if(info){info.innerHTML=`<b>${measure(h.referenceYards*.9144)}</b> ${units()}`;info.title='Published White tee scorecard distance';}const sub=$('.course-card p');if(sub)sub.textContent='9 holes · Par 36 · White tees · OSM map estimates';}}
function drawPosition(){if(!map)return;positionLayer.clearLayers();const p=origin();if(p){marker(p,'','player',positionLayer);if(course().source!=='demo'&&gps)L.circle(p,{radius:gps.accuracy,color:'#739ac9',weight:1,fillOpacity:.08}).addTo(positionLayer);}if(shotStart&&gps){L.polyline([shotStart.point,gps.point],{color:'#4775a8',weight:3,dashArray:'5 5'}).addTo(positionLayer);const el=$('#shot-live');if(el)el.innerHTML=`${measure(distance(shotStart.point,gps.point))} <small>${units()}</small>`;}}
function updateYardages(){if(view!=='play')return;const o=origin(),h=hole();for(const k of ['front','center','back'])$(`#yard-${k}`).textContent=measure(distance(o,h[k]));if(course().source==='demo'){$('#gps-pill').textContent='DEMO POSITION';$('#gps-status').textContent='Sample yardages · not a real course';}else{const good=fresh();$('#gps-pill').textContent=good?'LIVE GPS':watch!=null?'WAITING FOR GPS':'GPS OFF';$('#gps-status').textContent=good?`GPS ±${Math.round(gps.accuracy)} m · ${h.source==='OpenStreetMap'?'OSM green estimate':h.source==='manual'?'Your mapped points':'Check course mapping'}`:watch!=null?'Waiting for a fresh GPS fix. Keep the app open.':'Enable GPS to see live distances';$('#gps-status').classList.toggle('gps-warning',good&&gps.accuracy>20);if(good&&gps.accuracy>20)$('#gps-status').textContent+= ' · low accuracy';}drawPosition();if(target)drawTarget();}
function drawTarget(){if(!map)return;targetLayer.clearLayers();marker(target,'+','target',targetLayer);const p=origin()||hole().tee;if(p)L.polyline([p,target],{color:'#143f36',weight:2,dashArray:'5 5'}).addTo(targetLayer);if(hole().center)L.polyline([target,hole().center],{color:'#143f36',weight:2,dashArray:'5 5',opacity:.6}).addTo(targetLayer);const hint=$('#map-hint');if(hint)hint.textContent=`${measure(distance(p,target))} ${units()} ${origin()?'to target':'from tee (preview)'} · ${measure(distance(target,hole().center))} ${units()} to green`;}
async function mapClick(p){if(editor){if(editPoint==='hazard'){dialog('Mark a hazard','Save a point for a bunker, water edge, carry, or layup.',`<form id="hazard-form"><label class="field"><span>Label</span><input name="name" maxlength="70" placeholder="e.g. Bunker carry" required></label><button class="button full">Save hazard</button></form>`);$('#hazard-form').onsubmit=e=>{e.preventDefault();hole().hazards??=[];hole().hazards.push({name:new FormData(e.target).get('name'),point:p});save();close();render();};return;}hole()[editPoint]=p;hole().source='manual';const sequence=['tee','front','center','back'];const idx=sequence.indexOf(editPoint);if(idx<3)editPoint=sequence[idx+1];save();const center=map.getCenter(),zoom=map.getZoom();render();map.setView(center,zoom);toast('Point saved. Choose the next point or tap Done.');}else{target=p;drawTarget();}}
async function enableGps(){if(!navigator.geolocation){toast('This browser does not support location.');return;}if(watch!=null){if(gps&&map)map.panTo(gps.point);return;}watch=navigator.geolocation.watchPosition(p=>{gps={point:[p.coords.latitude,p.coords.longitude],accuracy:p.coords.accuracy,time:p.timestamp};updateYardages();if(view==='courses')toast('Location ready. Use Find nearby to search.');},e=>{if(e.code===1){navigator.geolocation.clearWatch(watch);watch=null;}toast(e.code===1?'Location blocked. Allow location in your browser’s site settings.':e.code===3?'GPS timed out. Move outdoors and try again.':'Location unavailable. Check your phone’s location setting.');updateYardages();},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});toast('Requesting GPS. Allow location when your browser asks.');try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}if(!gpsRefresh)gpsRefresh=setInterval(updateYardages,10000);}
function newRound(){let r=active();if(r)return r;r={id:uid(),courseId:course().id,name:course().name,date:new Date().toISOString(),demo:course().source==='demo',finished:false,holes:course().holes.map(h=>({number:h.number,par:h.par,score:null,putts:null})),shots:[]};state.rounds.unshift(r);save();return r;}
function quickScore(key,delta){const r=newRound(),h=r.holes[state.hole];h[key]=Math.max(key==='putts'?0:1,Math.min(key==='putts'?15:30,h[key]==null?(key==='putts'?2:hole().par)+(delta<0?-1:0):h[key]+delta));save();$('#quick-strokes').textContent=h.score??'—';$('#quick-putts').textContent=h.putts??'—';$('#quick-total').textContent=scoreTotal(r);$('#quick-relative').textContent=played(r).length?`${parText(relative(r))} through ${played(r).length}`:'No holes scored';}
function coursesView(){return heading('Your courses. Your collection.','Find a course, or build a map of your home track.',button('find',icon('plus')+' Add a course'))+`<div class="notice">Course data is saved on this device. OpenStreetMap coverage varies; check tee and green points before using yardages. An asterisk beside par means it needs verification.</div><div class="course-grid">${state.courses.map(c=>`<article class="card saved-course"><div class="course-art"><span>⚑</span></div><h2>${esc(c.name)}</h2><span class="tag">${c.source==='demo'?'FICTIONAL DEMO':esc(c.source)}</span><p>${c.holes.length} holes · ${c.holes.filter(h=>h.center).length} green centers mapped<br>${c.source==='demo'?'Try the features with sample data.':'Your personal course library.'}</p><div class="actions">${button('select-course','Play course','',`data-id="${esc(c.id)}"`)}${button('map-course','Map / photos','secondary',`data-id="${esc(c.id)}"`)}</div></article>`).join('')}<article class="card saved-course"><div class="course-art"><span>＋</span></div><h2>Know every yard.</h2><p>Map a course from aerial imagery, GPS coordinates, or points you mark on the ground.</p>${button('create-course','Create my own','secondary')}</article></div>`;}
function scoreView(){const r=active();if(!r)return heading('One stroke at a time.','Your digital scorecard.')+`<section class="card empty">${icon('scorecard')}<h3>A fresh card awaits.</h3><p>Start a round at ${esc(course().name)}. Record strokes and putts, and keep your round history on this device.</p>${button('start','Start a round')}</section>`;return heading('Every stroke tells a story.',`${esc(r.name)} · ${r.demo?'Demo round · ':''}${new Date(r.date).toLocaleDateString()}`,button('finish','Finish round','secondary'))+`<div class="stat-grid"><div class="card stat-box"><span class="label">TOTAL STROKES</span><strong>${scoreTotal(r)||'—'}</strong></div><div class="card stat-box"><span class="label">TO PAR</span><strong>${played(r).length?parText(relative(r)):'—'}</strong></div><div class="card stat-box"><span class="label">HOLES PLAYED</span><strong>${played(r).length}<small style="font-size:15px;color:#93a084"> / ${r.holes.length}</small></strong></div></div><section class="card table-wrap"><table class="score-table"><thead><tr><th>HOLE</th><th>PAR</th><th>STROKES</th><th>PUTTS</th><th>TO PAR</th></tr></thead><tbody>${r.holes.map((h,i)=>`<tr class="${state.hole===i?'current':''}"><td><button class="hole-link" data-action="go-hole" data-index="${i}">${String(h.number).padStart(2,'0')} ↗</button></td><td>${h.par}</td><td><input type="number" min="1" max="30" inputmode="numeric" data-score="score" data-index="${i}" value="${h.score??''}" aria-label="Hole ${h.number} strokes" placeholder="—"></td><td><input type="number" min="0" max="15" inputmode="numeric" data-score="putts" data-index="${i}" value="${h.putts??''}" aria-label="Hole ${h.number} putts" placeholder="—"></td><td>${h.score==null?'—':parText(h.score-h.par)}</td></tr>`).join('')}</tbody></table></section><p class="inline-note">Changes save automatically. Leave an unplayed hole blank. This is a personal scorecard; it does not calculate or submit an official handicap.</p>`;}
function bagView(){return heading('A club for every shot.','Set your typical carry distances. Distances are saved in yards.')+`<div class="notice">Use your normal carry distance, rather than your longest shot. Recorded GPS shots appear in Round history; club distances below are yours to edit.</div><div class="bag-grid">${state.bag.map((c,i)=>`<div class="card club"><h3>${esc(c.name)}</h3><input type="number" inputmode="numeric" value="${c.distance}" min="0" max="500" data-club="${i}" aria-label="${esc(c.name)} carry yards"><small> YD CARRY</small></div>`).join('')}</div>`;}
function roundsView(){const rs=state.rounds.filter(r=>r.finished);return heading('Good days, kept close.','Your rounds, scores, and the shots worth remembering.',button('export',icon('download')+' Export backup','secondary'))+(rs.length?rs.map(r=>`<article class="card round-card"><div><h3>${esc(r.name)} ${r.demo?'<span class="tag">DEMO</span>':''}</h3><p>${new Date(r.date).toLocaleDateString()} · ${played(r).length} holes · ${(r.shots||[]).length} tracked shots</p><button class="link" data-action="round-detail" data-id="${esc(r.id)}">View scorecard ↗</button></div><div style="text-align:right"><strong>${scoreTotal(r)}</strong><p>${parText(relative(r))} to par</p></div></article>`).join(''):`<div class="card empty">${icon('rounds')}<h3>The next round is a new story.</h3><p>Finish your first round to see your scorecard and tracked shots here. Active rounds are saved automatically.</p><a href="#play" class="button">Go play golf ${icon('arrow')}</a></div>`);}
async function findDialog(){dialog('Find your next fairway.','Search by course name and town, or find courses near your GPS location.',`<form id="search-form" class="search-row"><input name="q" placeholder="Course name, city…" minlength="3" maxlength="150" aria-label="Course name and city" required><button class="button">Search</button></form><div class="actions">${button('nearby',icon('gps')+' Find nearby','secondary small')}${button('create-course','Create manually','secondary small')}</div><p class="inline-note">Search: OpenStreetMap / Nominatim. Import: Overpass. These community services may be slow or unavailable.</p><div id="results"></div>`);$('#search-form').onsubmit=async e=>{e.preventDefault();const q=new FormData(e.target).get('q');$('#results').textContent='Searching courses and places…';try{const res=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&q=${encodeURIComponent(q)}`,{signal:AbortSignal.timeout(25000)});if(!res.ok)throw Error();searchResults=await res.json();showResults();}catch{$('#results').innerHTML='<p class="inline-note error">Search unavailable. Try again later or create a course manually.</p>';}};}
function showResults(){const el=$('#results');if(!el)return;el.innerHTML=searchResults.length?searchResults.map((r,i)=>`<button class="result" data-action="import-result" data-index="${i}"><strong>${esc(r.name||r.display_name.split(',')[0])}</strong><small>${esc(r.display_name)} · ${r.type==='golf_course'?'Golf course':'Place · manual mapping may be needed'}</small></button>`).join(''):'<p class="inline-note">No results. Try a course name with its town, or create one manually.</p>';}
async function overpass(query){const res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(query),signal:AbortSignal.timeout(55000)});if(!res.ok)throw Error('Course service is busy. Try again later or create the course manually.');const data=await res.json();if(data.remark)throw Error('Course query did not finish. Try again later.');return data.elements;}
async function nearby(){if(!fresh()){await enableGps();toast('Allow GPS, then tap Find nearby again once your location is ready.');return;}$('#results').textContent='Looking for golf courses within 25 km…';try{const [a,b]=gps.point;const els=await overpass(`[out:json][timeout:35];nwr["leisure"="golf_course"](around:25000,${a},${b});out center tags;`);searchResults=els.filter(e=>e.center||e.lat).map(e=>({osm_type:e.type,osm_id:e.id,name:e.tags?.name||'Unnamed golf course',type:'golf_course',display_name:e.tags?.name||'Unnamed golf course',lat:e.center?.lat??e.lat,lon:e.center?.lon??e.lon}));showResults();}catch(e){$('#results').textContent=e.message;}}
async function importCourse(i){const result=searchResults[i];if(!result)return;$('#results').textContent='Loading mapped holes… this can take a moment.';try{let els=[];if(result.type==='golf_course'&&['way','relation'].includes(result.osm_type)){els=await overpass(`[out:json][timeout:35];${result.osm_type}(${Number(result.osm_id)});map_to_area->.course; nwr(area.course)["golf"="hole"];out geom;`);}const c=osmCourse(result,els);state.courses.push(c);state.selected=c.id;state.hole=0;save();close();location.hash='play';view='play';editor=!els.length;editPoint='tee';layer='course';render();toast(els.length?'Course imported. Verify green centers and map front/back points before play.':'Course location saved. Add hole points with the course mapper.');}catch(e){$('#results').textContent=e.message;}}
function createDialog(){dialog('Your own home course.','Start with a location, then mark each tee and green on the map.',`<form id="create-form"><label class="field"><span>Course name</span><input name="name" required maxlength="100" placeholder="My golf course"></label><div class="field-row"><label class="field"><span>Latitude</span><input name="lat" required type="number" step="any" min="-85" max="85" value="${gps?.point[0]??''}" placeholder="e.g. 40.75"></label><label class="field"><span>Longitude</span><input name="lon" required type="number" step="any" min="-180" max="180" value="${gps?.point[1]??''}" placeholder="e.g. -73.95"></label></div><label class="field"><span>Number of holes</span><select name="count"><option>9</option><option selected>18</option></select></label><button class="button full">Create course & open mapper</button></form><p class="inline-note">Coordinates set the map’s starting location. Mark the actual tee and green points for every hole.</p>`);$('#create-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=[Number(f.get('lat')),Number(f.get('lon'))];if(!validPoint(p))return toast('Enter valid latitude and longitude.');const c={id:uid(),name:f.get('name').trim(),source:'My mapping',center:p,holes:Array.from({length:Number(f.get('count'))},(_,i)=>({number:i+1,par:4,parEstimated:true,source:'manual',hazards:[]}))};state.courses.push(c);state.selected=c.id;state.hole=0;save();close();view='play';location.hash='play';editor=true;editPoint='tee';render();};}
function finishDialog(){const r=active();if(!r)return;dialog('Call it a round.','Save this scorecard to your personal round history.',`<div class="notice">${played(r).length} of ${r.holes.length} holes recorded · ${scoreTotal(r)} strokes · ${parText(relative(r))} to par on scored holes.</div>${!played(r).length?'<p class="dialog-copy">No scores recorded yet. You can still save this round and its tracked shots.</p>':''}${button('finish-confirm','Save & finish round','full')}`);}
function roundDetail(id){const r=state.rounds.find(r=>r.id===id);if(!r)return;dialog(esc(r.name),`${new Date(r.date).toLocaleDateString()} · ${r.demo?'Demo round':'Personal scorecard'}`,`<div class="table-wrap"><table class="score-table"><thead><tr><th>HOLE</th><th>PAR</th><th>SCORE</th><th>PUTTS</th></tr></thead><tbody>${r.holes.map(h=>`<tr><td>${h.number}</td><td>${h.par}</td><td>${h.score??'—'}</td><td>${h.putts??'—'}</td></tr>`).join('')}</tbody></table></div><div class="dialog-section"><h3>Tracked shots</h3>${(r.shots||[]).length?r.shots.map(s=>`<p class="dialog-copy">Hole ${esc(s.hole)} · ${esc(s.club)} · ${measure(s.meters)} ${units()} · GPS ±${Math.round(s.accuracy)} m</p>`).join(''):'<p class="dialog-copy">No shots recorded.</p>'}</div>`);}
async function trackShot(){if(course().source==='demo')return toast('Shot tracking needs a real course and live GPS. Add or select your course first.');if(!fresh()||gps.accuracy>30)return toast('Enable GPS and wait for a fresh fix within ±30 m before tracking a shot.');if(!shotStart){shotStart={point:[...gps.point],accuracy:gps.accuracy,time:Date.now(),hole:hole().number,courseId:course().id};toast('Shot started. Walk to your ball, then tap Stop.');render();return;}if(shotStart.courseId!==course().id)return toast('Return to the course where you started this shot.');const meters=distance(shotStart.point,gps.point);dialog('Make that shot count.',`${measure(meters)} ${units()} · GPS uncertainty up to ±${Math.round(shotStart.accuracy+gps.accuracy)} m`, `<form id="shot-form"><label class="field"><span>Club</span><select name="club">${state.bag.map(c=>`<option>${esc(c.name)}</option>`).join('')}<option>Other</option></select></label><button class="button full">Save shot</button></form><div class="actions">${button('cancel-shot','Discard shot','secondary small')}</div>`);const end=[...gps.point],accuracy=shotStart.accuracy+gps.accuracy;$('#shot-form').onsubmit=e=>{e.preventDefault();newRound().shots.push({hole:shotStart.hole,club:new FormData(e.target).get('club'),start:shotStart.point,end,meters,accuracy,date:new Date().toISOString()});shotStart=null;save();close();render();toast('Shot saved to your round.');};}
function help(){dialog('Meet your personal caddie.','A free personal golf toolkit. No subscription or API key required.',`<div class="dialog-copy"><ol class="help-list"><li><b>Add your course.</b> Search for a course, find one nearby, or create it with coordinates.</li><li><b>Check the map.</b> OpenStreetMap hole lines give an estimated green center. Mark front/back, verify par, and add hazards in the course mapper.</li><li><b>Turn on GPS.</b> Allow location and keep the app open for current distances. A phone’s GPS and mapped points both affect accuracy.</li><li><b>Play your round.</b> Record strokes and putts. Tap the map to measure a target. Start a shot, walk to the ball, then stop and save it.</li><li><b>Make a backup.</b> Export from Preferences or Round history. Device data can be lost when browser storage is cleared.</li></ol><hr><b>Photos and aerials</b><p>A GPS photo records the camera location, not the locations of greens in view. JPEG GPS tags are read when available; otherwise you can enter coordinates. For overhead mapping, upload your own north-up, corrected aerial image and enter its geographic bounds. A single ground photo cannot produce a reliable course map or green slopes.</p><b>On your phone</b><p>Open this app in Safari or Chrome, then use Share → Add to Home Screen on iPhone, or the browser’s Install / Add to Home screen menu on Android. GPS needs HTTPS (or localhost for development). Keep Fairway in the foreground; background and watch GPS are not supported.</p><b>Free data, with limits</b><p>Course points, scores, photos, and the cached app shell can work offline after a successful first load. Online map tiles and course search require internet. No offline tile downloads. US aerial coverage and detail vary. Third-party services and hosting availability may change.</p><p>Data: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap / ODbL</a> · <a href="https://operations.osmfoundation.org/policies/tiles/" target="_blank" rel="noopener">Map policy</a> · <a href="https://www.usgs.gov/the-national-map-data-delivery/gis-data-download" target="_blank" rel="noopener">USGS imagery</a>. Local data stays on this device; map providers receive map requests, course search receives your search, and nearby search receives location.</p></div>`);}
function settings(){dialog('Make yourself at home.','Personal preferences and backups.',`<label class="field"><span>Distance units</span><select id="units-select"><option value="yd" ${state.units==='yd'?'selected':''}>Yards</option><option value="m" ${state.units==='m'?'selected':''}>Meters</option></select></label><div class="dialog-section"><h3>Your data, in your hands.</h3><p class="dialog-copy">Scores, courses, photos, and club distances stay in this browser. Export a backup to move to another device or browser.</p><div class="actions">${button('export',icon('download')+' Export backup')}${button('import-backup','Import backup','secondary')}</div><input id="backup-file" type="file" accept="application/json,.json" hidden></div><div class="dialog-section"><h3>Location</h3><p class="dialog-copy">${watch!=null?'GPS is active while this app is open.':'GPS is currently off.'}</p>${button(watch!=null?'gps-off':'gps',watch!=null?'Turn GPS off':'Enable GPS','secondary')}</div>${button('help','Read the quick guide','secondary full','style="margin-top:20px"')}`);$('#units-select').onchange=e=>{state.units=e.target.value;save();render();};$('#backup-file').onchange=e=>importBackup(e.target.files[0]);}
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('fairway-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function dbAll(){const db=await dbPromise;return new Promise((resolve,reject)=>{const r=db.transaction('photos').objectStore('photos').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbPut(p){const db=await dbPromise;return new Promise((resolve,reject)=>{const t=db.transaction('photos','readwrite');t.objectStore('photos').put(p);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
async function loadPhotos(){const id=course().id,m=map;try{photos=(await dbAll()).filter(p=>p.courseId===id);if(!map||map!==m)return;for(const p of photos){if(p.bounds){L.imageOverlay(p.image,p.bounds,{opacity:.8}).addTo(overlayLayers);}else if(p.point){const mk=marker(p.point,'▣','photo',overlayLayers);mk.on('click',()=>showPhoto(p.id));}}}catch{toast('Photo storage is unavailable in this browser.');}}
function showPhoto(id){const p=photos.find(p=>p.id===id);if(!p)return;dialog(esc(p.name),'Camera position · saved on this device',`<img class="photo-preview" src="${esc(p.image)}" alt="${esc(p.name)}"><p class="inline-note">${p.point?.map(n=>n.toFixed(6)).join(', ')||'Georeferenced aerial image'}</p>`);}
function photoDialog(){photoDraft=null;dialog('A little local knowledge.','Attach your own course photo at its camera location.',`<label class="field"><span>JPEG, PNG, or WebP · up to 12 MB</span><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="photo-preview"></div><form id="photo-form"><label class="field"><span>Photo label</span><input name="name" required maxlength="100" placeholder="e.g. Approach to the 4th green"></label><div class="field-row"><label class="field"><span>Camera latitude</span><input id="photo-lat" name="lat" type="number" step="any" min="-85" max="85" required></label><label class="field"><span>Camera longitude</span><input id="photo-lon" name="lon" type="number" step="any" min="-180" max="180" required></label></div><p class="inline-note" id="exif-status">GPS metadata is read from JPEGs when available. You can also enter the camera coordinates.</p><button class="button full">Save course photo</button></form>`);$('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const point=gpsFromJpeg(await file.arrayBuffer());photoDraft=await imageData(file);$('#photo-preview').innerHTML=`<img class="photo-preview" src="${photoDraft}" alt="Selected course photo">`;if(point){$('#photo-lat').value=point[0];$('#photo-lon').value=point[1];$('#exif-status').textContent='GPS camera coordinates found. Check them before saving.';}else $('#exif-status').textContent='No GPS tags found. Enter the camera’s latitude and longitude.';}catch(e){toast(e.message);}};$('#photo-form').onsubmit=async e=>{e.preventDefault();if(!photoDraft)return toast('Choose a photo first.');const f=new FormData(e.target),p=[Number(f.get('lat')),Number(f.get('lon'))];if(!validPoint(p))return toast('Enter valid camera coordinates.');try{await dbPut({id:uid(),courseId:course().id,name:f.get('name'),point:p,image:photoDraft});close();render();toast('Course photo saved on this device.');}catch{toast('Photo could not be saved. Storage may be full.');}};}
async function imageData(file){if(file.size>12*1024*1024)throw Error('Choose an image smaller than 12 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG, or WebP image.');const img=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close();return canvas.toDataURL('image/jpeg',.88);}
function overlayDialog(){photoDraft=null;dialog('Bring your own aerial.', 'Align a north-up aerial image using its known geographic bounds.',`<p class="inline-note">Use your own or permission-cleared orthorectified image. Enter the exact outer bounds. Ordinary ground photos and rotated screenshots won’t align correctly.</p><label class="field"><span>Aerial image · up to 12 MB</span><input id="aerial-file" type="file" accept="image/jpeg,image/png,image/webp"></label><form id="aerial-form"><div class="field-row"><label class="field"><span>North latitude</span><input name="north" type="number" step="any" min="-85" max="85" required></label><label class="field"><span>South latitude</span><input name="south" type="number" step="any" min="-85" max="85" required></label></div><div class="field-row"><label class="field"><span>West longitude</span><input name="west" type="number" step="any" min="-180" max="180" required></label><label class="field"><span>East longitude</span><input name="east" type="number" step="any" min="-180" max="180" required></label></div><button class="button full">Add aerial overlay</button></form>`);$('#aerial-file').onchange=async e=>{try{photoDraft=await imageData(e.target.files[0]);toast('Image loaded. Enter the geographic bounds to align it.');}catch(e){toast(e.message);}};$('#aerial-form').onsubmit=async e=>{e.preventDefault();if(!photoDraft)return toast('Select an aerial image first.');const f=new FormData(e.target),n=Number(f.get('north')),s=Number(f.get('south')),w=Number(f.get('west')),east=Number(f.get('east'));if(!validPoint([n,w])||!validPoint([s,east])||n<=s||east<=w||n-s>.1||east-w>.1)return toast('Check your bounds: north > south, east > west, and each span under 0.1° for a course.');try{await dbPut({id:uid(),courseId:course().id,name:'My aerial image',bounds:[[s,w],[n,east]],image:photoDraft});close();render();map.fitBounds([[s,w],[n,east]]);toast('Aerial added. Mark tee and green points over the image.');}catch{toast('Aerial could not be saved. Storage may be full.');}};}
async function exportBackup(){try{const data={format:'fairway-backup',version:1,exported:new Date().toISOString(),courses:state.courses,rounds:state.rounds,bag:state.bag,units:state.units,photos:await dbAll()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fairway-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Backup downloaded. Keep it somewhere safe.');}catch{toast('Backup failed. Device photo storage may be unavailable.');}}
async function importBackup(file){if(!file)return;if(file.size>50*1024*1024)return toast('Backup is too large. Maximum 50 MB.');try{const data=validateBackup(JSON.parse(await file.text()));if(data.photos!=null&&(!Array.isArray(data.photos)||data.photos.length>500||data.photos.some(p=>typeof p.id!=='string'||typeof p.courseId!=='string'||typeof p.name!=='string'||typeof p.image!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(p.image)||!p.point&&!p.bounds||p.point&&!validPoint(p.point)||p.bounds&&(!Array.isArray(p.bounds)||p.bounds.length!==2||!p.bounds.every(validPoint)))))throw Error('Invalid photo data in backup.');for(const c of data.courses){const i=state.courses.findIndex(v=>v.id===c.id);if(i>=0)state.courses[i]=c;else state.courses.push(c);}for(const r of data.rounds){const i=state.rounds.findIndex(v=>v.id===r.id);if(i>=0)state.rounds[i]=r;else state.rounds.push(r);}for(const p of data.photos||[])await dbPut(p);if(data.bag)state.bag=data.bag;if(['yd','m'].includes(data.units))state.units=data.units;state.selected=state.courses[0].id;state.hole=0;save();close();render();toast('Backup merged. Matching courses and rounds were updated.');}catch(e){toast(e.message||'Could not import this backup.');}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){case'close':close();break;case'help':help();break;case'settings':settings();break;case'find':findDialog();break;case'nearby':nearby();break;case'import-result':importCourse(Number(b.dataset.index));break;case'create-course':createDialog();break;case'select-course':case'map-course':if(shotStart)return toast('Save or discard your current shot before changing courses.');state.selected=b.dataset.id;state.hole=0;save();view='play';location.hash='play';editor=a==='map-course';editPoint='tee';target=null;render();break;case'prev':case'next':state.hole=Math.max(0,Math.min(course().holes.length-1,state.hole+(a==='next'?1:-1)));target=null;save();render();break;case'go-hole':state.hole=Number(b.dataset.index);save();location.hash='play';break;case'gps':await enableGps();break;case'gps-off':if(watch!=null)navigator.geolocation.clearWatch(watch);watch=null;gps=null;wakeLock?.release();clearInterval(gpsRefresh);gpsRefresh=null;render();settings();break;case'start':newRound();toast('Round started. Your scorecard saves automatically.');render();break;case'stroke-plus':quickScore('score',1);break;case'stroke-minus':quickScore('score',-1);break;case'putt-plus':quickScore('putts',1);break;case'putt-minus':quickScore('putts',-1);break;case'finish':finishDialog();break;case'finish-confirm':if(active()){active().finished=true;save();}close();render();toast('Round saved to your history.');break;case'round-detail':roundDetail(b.dataset.id);break;case'shot':trackShot();break;case'cancel-shot':shotStart=null;close();render();toast('Shot discarded.');break;case'edit':editor=!editor;editPoint='tee';target=null;render();break;case'editor-done':editor=false;render();break;case'edit-point':editPoint=b.dataset.value;{const center=map.getCenter(),zoom=map.getZoom();render();map.setView(center,zoom);}break;case'clear-target':target=null;render();break;case'layer':layer=b.dataset.value;render();break;case'photo':photoDialog();break;case'overlay':overlayDialog();break;case'clear-hole':dialog('Clear mapped points?',`Remove tee, green, and hazard points from hole ${hole().number}.`,button('clear-hole-confirm','Clear this hole','danger full'));break;case'clear-hole-confirm':for(const k of ['tee','front','center','back'])delete hole()[k];hole().hazards=[];save();close();render();break;case'export':exportBackup();break;case'import-backup':$('#backup-file')?.click();break;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-score]')){const r=active();if(!r)return;const input=e.target,key=input.dataset.score,n=input.value===''?null:Number(input.value);if(n!=null&&(!Number.isInteger(n)||n<(key==='putts'?0:1)||n>(key==='putts'?15:30))){toast('Enter a valid whole number or leave the hole blank.');input.value=r.holes[Number(input.dataset.index)][key]??'';return;}r.holes[Number(input.dataset.index)][key]=n;save();render();}if(e.target.matches('[data-club]')){const n=Number(e.target.value);if(!Number.isFinite(n)||n<0||n>500){toast('Enter a carry distance between 0 and 500 yards.');return;}state.bag[Number(e.target.dataset.club)].distance=n;save();}if(e.target.id==='edit-par'){hole().par=Number(e.target.value);hole().parEstimated=false;const r=active();if(r)r.holes[state.hole].par=hole().par;save();}});
function connection(){const el=$('#connection');el.innerHTML=`<i style="background:${navigator.onLine?'#739752':'#bd9654'}"></i> ${navigator.onLine?'Online':'Offline'}`;}
window.addEventListener('online',connection);window.addEventListener('offline',connection);window.addEventListener('hashchange',navigate);document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&watch!=null){updateYardages();try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
navigate();
